class Solution:
    def numSubarraysWithSum(self, nums: List[int], goal: int) -> int:
        my_dict = {0:1}
        accum, res = 0, 0
        for n in nums:
            accum += n
            diff = accum-goal
            if diff in my_dict:
                res += my_dict[diff]
            if accum in my_dict:
                my_dict[accum] +=1
            else:
                my_dict[accum] =1
        return res

class Solution:
    def queryString(self, S: str, N: int) -> bool:
        ans = set()
        for i in range(len(S)):
            for ii in range(i, i + N.bit_length()): 
                x = int(S[i:ii+1], 2)
                if 1 <= x <= N: ans.add(x)
        return len(ans) == N

class Solution:
    def maxSatisfied(self, customers, grumpy, X):
        result, max_extra, extra = 0, 0, 0
        for i in range(len(customers)):
            result += 0 if grumpy[i] else customers[i]
            extra += customers[i] if grumpy[i] else 0
            if i >= X:
                extra -= customers[i-X] if grumpy[i-X] else 0
            max_extra = max(max_extra, extra)
        return result + max_extra

class Solution:
    def balancedString(self, s):
        count = collections.Counter(s)
        res = n = len(s)
        if all(n/4==count[char] for char in 'QWER'):
            return 0
        left = 0
        for right, char in enumerate(s):
            # replace char whose index==right to check if it is balanced
            count[char] -= 1
            # if it is balanced, window shrinks to get the smallest length of window
            while left <= right and all(n / 4 >= count[char] for char in 'QWER'):
                res = min(res, right - left + 1)
                count[s[left]] =count[s[left]]+ 1
                left += 1
        return res

class Solution:
    def numberOfSubstrings(self, s: str) -> int:
        start = 0
        end = 0
        counter = 0
        store = {'a' : 0, 'b' : 0, 'c' : 0}

        for end in range(len(s)):
            store[s[end]] += 1

            while store['a'] > 0 and store['b'] > 0 and store['c'] > 0:
                counter += (len(s) - end)
                store[s[start]] -= 1
                start += 1

        return counter
